 import { MeshBasicNodeMaterial, PlaneGeometry } from 'three/webgpu';
import {
  texture,
  uv,
  vec2,
  color,
  mix,
  smoothstep,
  fract,
  sin,
  dot,
  add,
  sub,
  mul,
  uniform,
} from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    RGBAFormat,
    SRGBColorSpace,
    DataTexture,
    ClampToEdgeWrapping,
    LinearFilter,
    LinearMipmapLinearFilter,
  } = THREE;

  const visual = config.intent?.visualSpec ?? {};
  const specColors = visual.colors ?? {};
  const ink = specColors.ink ?? '#16161d';
  const surface = specColors.surface ?? '#0b0b10';

  const group = new THREE.Group();
  group.name = config.id ?? 'journal-card-1';

  const timelines = [];

  const src = config.atlasRegion?.sourceRect ?? { x: 0, y: 0, w: 512, h: 320 };
  const aspect = src.w / src.h;
  const height = 1.0;
  const width = aspect * height;

  const geometry = new PlaneGeometry(width, height);

  const placeholderData = new Uint8Array([22, 22, 29, 255]);
  const placeholderTex = new DataTexture(placeholderData, 1, 1, RGBAFormat);
  placeholderTex.colorSpace = SRGBColorSpace;
  placeholderTex.needsUpdate = true;

  const texUniform = uniform(placeholderTex);

  const vUV = uv();
  const texSample = texture(texUniform, vUV);

  const gradient = mix(color(surface), color(ink), smoothstep(0.0, 1.0, vUV.y));
  const base = mix(gradient, texSample, texSample.a);

  const grain = fract(sin(dot(vUV, vec2(12.9898, 78.233))).mul(43758.5453));
  const grainMod = mul(sub(grain, 0.5), 0.04);

  const finalColor = add(base, grainMod);

  const material = new MeshBasicNodeMaterial({
    colorNode: finalColor,
    transparent: false,
    side: THREE.FrontSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'card-plane';
  group.add(mesh);

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        tex.colorSpace = SRGBColorSpace;
        tex.wrapS = ClampToEdgeWrapping;
        tex.wrapT = ClampToEdgeWrapping;
        tex.magFilter = LinearFilter;
        tex.minFilter = LinearMipmapLinearFilter;
        tex.generateMipmaps = true;
        tex.needsUpdate = true;

        texUniform.value = tex;
        material.needsUpdate = true;
      })
      .catch(() => {
        // Retain placeholder on failure; card still renders the gradient surface.
      });
  }

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach((t) => {
      try {
        t.kill();
      } catch {}
    });

    mesh.geometry.dispose();
    material.dispose();

    const liveTex = texUniform.value;
    if (liveTex && liveTex !== placeholderTex) {
      liveTex.dispose();
    }
    placeholderTex.dispose();
  };

  return group;
}
